const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    const donnerPass = ee.Geometry.Point([-120.3255, 39.3305]); // Approximate center of Donner Pass
    const startDate = '2022-01-01';
    const endDate = '2022-04-30';
    const targetSWEInches = 40;
    const scale = 3000; // Use a reasonable scale to avoid memory issues and ensure timely processing

    // 2. Data Acquisition & Check
    let snodas = ee.ImageCollection('NOAA/NOHRSC/SNODAS/V1')
      .filterBounds(donnerPass)
      .filterDate(startDate, endDate)
      .select('SWE'); // Select Snow Water Equivalent band

    const initialSize = await snodas.size().getInfo();
    console.log(`SNODAS images found for Jan-Apr 2022: ${initialSize}`);

    if (initialSize === 0) {
      console.log("C1: Empty Collection (No SNODAS images found for the specified date range and location).");
      return;
    }

    // 3. Processing
    // SNODAS SWE is in millimeters (mm).
    // Summing daily SWE values over the period.
    const sumSWE = snodas.sum();

    // Reduce the sumSWE image over the Donner Pass geometry to get the total SWE.
    const reducedSWE = await sumSWE.reduceRegion({
      reducer: ee.Reducer.mean(), // Using mean since sum() was applied to the collection already
      geometry: donnerPass,
      scale: scale,
      maxPixels: 1e9,
      crs: 'EPSG:4326' // Specify CRS for consistency
    }).get('SWE');

    const totalSweMm = await reducedSWE.getInfo();

    // Check for C3 (Calculation Failure)
    if (totalSweMm === null || isNaN(totalSweMm)) {
      console.log("C3: Calculation Failure (Result is None or NaN after reducing SWE).");
      return;
    }

    // Convert total SWE from mm to inches (1 inch = 25.4 mm)
    const totalSweInches = totalSweMm / 25.4;

    // Check for C2 (No Valid Pixels) - although `totalSweMm` would be 0 in that case,
    // a valid 0 is not a C2 but an answer B.
    // If the image collection was empty or all pixels were masked, it would have been caught by C1 or by totalSweMm being null.

    // 5. Validation & Final Answer
    console.log(`Donner Pass Total SWE (Jan-Apr 2022): ${totalSweMm.toFixed(2)} mm`);
    console.log(`Donner Pass Total SWE (Jan-Apr 2022): ${totalSweInches.toFixed(2)} inches`);

    if (totalSweInches > targetSWEInches) {
      console.log("A");
    } else {
      console.log("B");
    }

  } catch (error) {
    console.error("D: An error occurred during processing:", error);
    console.log("D");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
